def norm_sg09(rows):
    result = []
    for row in rows:
        # ① 每行里连续 3 个以上的空白字符都换成一个「-」（不足 3 个的空白原样保留）
        new_row = ""
        i = 0
        while i < len(row):
            if row[i].isspace():
                count = 1
                while i + count < len(row) and row[i + count].isspace():
                    count += 1
                if count > 3:
                    new_row += "-"
                else:
                    new_row += row[i:i+count]
                i += count
            else:
                new_row += row[i]
                i += 1
        # ② 去掉每行首尾的空白字符
        new_row = new_row.strip()
        if not new_row:
            continue

        result.append(new_row)

    # ③ 去掉紧挨着的重复行：只有内容完全相同且前后相邻的才去掉，不相邻的重复行必须保留
    filtered_result = []
    for i in range(len(result)):
        if not filtered_result:
            filtered_result.append(result[i])
        else:
            if result[i] != filtered_result[-1]:
                filtered_result.append(result[i])

    # ④ 按文本字典序降序排列
    filtered_result.sort(reverse=True)

    # ⑤ 每行只保留末尾的 9 个字符（前面超出的直接截掉）
    final_result = []
    for row in filtered_result:
        if len(row) <= 9:
            final_result.append(row)
        else:
            final_result.append(row[-9:])

    return final_result

